hints.tier2Scaffold:
WITH closes AS (
  SELECT day, price FROM price_ticks WHERE symbol='NVAX' AND hour=15
), flags AS (
  SELECT day, CASE WHEN price > LAG(price) OVER (ORDER BY day) THEN 1 ELSE 0 END AS up
  FROM closes
), grp AS (
  SELECT day, up,
         ROW_NUMBER() OVER (ORDER BY day) - ROW_NUMBER() OVER (PARTITION BY up ORDER BY day) AS g
  FROM flags
)
SELECT MAX(streak) AS longest_up_streak FROM (
  SELECT COUNT(*) AS streak FROM grp WHERE up = 1 GROUP BY g
);

WITH vol AS (
  SELECT a.sector, t.symbol, SUM(t.volume) AS total_vol
  FROM price_ticks t JOIN assets a ON a.symbol = t.symbol
  GROUP BY a.sector, t.symbol
), ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY sector ORDER BY total_vol DESC) AS rn FROM vol
)
SELECT sector, symbol, total_vol FROM ranked WHERE rn <= ___
ORDER BY sector, total_vol DESC;

WITH closes AS (
  SELECT day, price AS close FROM price_ticks WHERE symbol='QBIT' AND hour=15
), dd AS (
  SELECT day, close,
         MAX(close) OVER (ORDER BY day) AS peak
  FROM closes
)
SELECT ROUND(MIN((close / peak - 1) * 100), 2) AS max_drawdown_pct FROM dd;
